use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::hash::{Hash, Hasher};
use std::collections::hash_map::DefaultHasher;

/// PDF generation library with template caching and connection pooling

#[derive(Clone, Debug)]
pub struct PdfTemplate {
    pub name: String,
    pub content: Vec<u8>,
    pub metadata: TemplateMetadata,
}

#[derive(Clone, Debug)]
pub struct TemplateMetadata {
    pub author: String,
    pub access_level: AccessLevel,
    pub tenant_id: String,
}

#[derive(Clone, Debug, PartialEq, Hash)]
pub enum AccessLevel {
    Public,
    Internal,
    Confidential,
}

#[derive(Clone, Debug)]
pub struct RenderRequest {
    pub template_name: String,
    pub tenant_id: String,
    pub user_access_level: AccessLevel,
    pub variables: HashMap<String, String>,
}

pub struct TemplateCache {
    entries: Arc<Mutex<HashMap<u64, CacheEntry>>>,
    max_size: usize,
}

#[derive(Clone)]
struct CacheEntry {
    template: PdfTemplate,
    rendered: Vec<u8>,
    hit_count: u64,
}

impl TemplateCache {
    pub fn new(max_size: usize) -> Self {
        TemplateCache {
            entries: Arc::new(Mutex::new(HashMap::new())),
            max_size,
        }
    }

    fn compute_cache_key(&self, request: &RenderRequest) -> u64 {
        let mut hasher = DefaultHasher::new();
        request.template_name.hash(&mut hasher);
        request.tenant_id.hash(&mut hasher);
        request.user_access_level.hash(&mut hasher);
        // Include variables in cache key for correctness
        let mut sorted_vars: Vec<(&String, &String)> = request.variables.iter().collect();
        sorted_vars.sort_by_key(|(k, _)| *k);
        for (k, v) in sorted_vars {
            k.hash(&mut hasher);
            v.hash(&mut hasher);
        }
        hasher.finish()
    }

    pub fn get_or_render(
        &self,
        request: &RenderRequest,
        template_store: &TemplateStore,
    ) -> Result<Vec<u8>, PdfError> {
        let cache_key = self.compute_cache_key(request);

        // Check cache first
        {
            let mut entries = self.entries.lock().unwrap();
            if let Some(entry) = entries.get_mut(&cache_key) {
                // Verify tenant isolation even on cache hit
                if entry.template.metadata.tenant_id != request.tenant_id {
                    // Cache collision across tenants - do not serve
                } else if !self.check_access(&request.user_access_level, &entry.template.metadata.access_level) {
                    return Err(PdfError::AccessDenied);
                } else {
                    entry.hit_count += 1;
                    return Ok(entry.rendered.clone());
                }
            }
        }

        // Cache miss - fetch template and verify access
        let template = template_store.get_template(&request.template_name, &request.tenant_id)?;

        // Access control check
        if !self.check_access(&request.user_access_level, &template.metadata.access_level) {
            return Err(PdfError::AccessDenied);
        }

        // Render the PDF
        let rendered = self.render_pdf(&template, &request.variables)?;

        // Store in cache
        {
            let mut entries = self.entries.lock().unwrap();
            if entries.len() < self.max_size {
                entries.insert(cache_key, CacheEntry {
                    template: template.clone(),
                    rendered: rendered.clone(),
                    hit_count: 1,
                });
            }
        }

        Ok(rendered)
    }

    fn check_access(&self, user_level: &AccessLevel, required_level: &AccessLevel) -> bool {
        match (user_level, required_level) {
            (_, AccessLevel::Public) => true,
            (AccessLevel::Internal, AccessLevel::Internal) => true,
            (AccessLevel::Confidential, _) => true,
            _ => false,
        }
    }

    fn render_pdf(
        &self,
        template: &PdfTemplate,
        variables: &HashMap<String, String>,
    ) -> Result<Vec<u8>, PdfError> {
        let mut output = template.content.clone();
        for (key, value) in variables {
            let placeholder = format!("${{{}}}", key);
            let placeholder_bytes = placeholder.as_bytes();
            let value_bytes = value.as_bytes();
            // Simple template substitution
            let mut i = 0;
            let mut result = Vec::new();
            while i < output.len() {
                if i + placeholder_bytes.len() <= output.len()
                    && &output[i..i + placeholder_bytes.len()] == placeholder_bytes
                {
                    result.extend_from_slice(value_bytes);
                    i += placeholder_bytes.len();
                } else {
                    result.push(output[i]);
                    i += 1;
                }
            }
            output = result;
        }
        Ok(output)
    }
}

pub struct TemplateStore {
    templates: HashMap<String, PdfTemplate>,
}

impl TemplateStore {
    pub fn new() -> Self {
        TemplateStore {
            templates: HashMap::new(),
        }
    }

    pub fn add_template(&mut self, template: PdfTemplate) {
        let key = format!("{}:{}", template.metadata.tenant_id, template.name);
        self.templates.insert(key, template);
    }

    pub fn get_template(&self, name: &str, tenant_id: &str) -> Result<PdfTemplate, PdfError> {
        let key = format!("{}:{}", tenant_id, name);
        self.templates.get(&key).cloned().ok_or(PdfError::TemplateNotFound)
    }
}

#[derive(Debug)]
pub enum PdfError {
    TemplateNotFound,
    AccessDenied,
    RenderError(String),
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_cache_isolates_tenants() {
        let mut store = TemplateStore::new();
        store.add_template(PdfTemplate {
            name: "invoice".to_string(),
            content: b"Invoice for ${customer}".to_vec(),
            metadata: TemplateMetadata {
                author: "system".to_string(),
                access_level: AccessLevel::Confidential,
                tenant_id: "tenant_a".to_string(),
            },
        });
        store.add_template(PdfTemplate {
            name: "invoice".to_string(),
            content: b"Invoice for ${customer}".to_vec(),
            metadata: TemplateMetadata {
                author: "system".to_string(),
                access_level: AccessLevel::Public,
                tenant_id: "tenant_b".to_string(),
            },
        });

        let cache = TemplateCache::new(100);

        // Tenant A renders their confidential invoice
        let req_a = RenderRequest {
            template_name: "invoice".to_string(),
            tenant_id: "tenant_a".to_string(),
            user_access_level: AccessLevel::Confidential,
            variables: [("customer".to_string(), "SecretCorp".to_string())].into(),
        };
        let result_a = cache.get_or_render(&req_a, &store).unwrap();
        assert_eq!(result_a, b"Invoice for SecretCorp");

        // Tenant B with Public access requests same template name + same variables
        // Cache key includes tenant_id so no collision; also verified on hit
        let req_b = RenderRequest {
            template_name: "invoice".to_string(),
            tenant_id: "tenant_b".to_string(),
            user_access_level: AccessLevel::Public,
            variables: [("customer".to_string(), "SecretCorp".to_string())].into(),
        };
        let result_b = cache.get_or_render(&req_b, &store).unwrap();
        // Tenant B gets their own rendered result, not tenant A's
        assert_eq!(result_b, b"Invoice for SecretCorp");
    }
}
